.ds-device__ear { grid-row: 1 / span 2; background: linear-gradient(90deg, #0a0807, #1e1916 50%, #0a0807); border-radius: 8px 0 0 8px; position: relative; }
.ds-device__ear--r { border-radius: 0 8px 8px 0; }
.ds-device__ear::before, .ds-device__ear::after {
  content: ""; position: absolute; left: 50%; width: 10px; height: 10px; margin-left: -5px; border-radius: 50%;
  background: radial-gradient(circle at 35% 35%, #e9e8e2, #8a8985 55%, #3d3c39 100%);
  box-shadow: 0 1px 0 #fff4, inset 0 0 0 1px #0008;
}
.ds-device__ear::before { top: 12px; }
.ds-device__ear::after { bottom: 12px; }
.ds-device__ear::before { background-image: linear-gradient(45deg, transparent 45%, #222 45%, #222 55%, transparent 55%), radial-gradient(circle at 35% 35%, #e9e8e2, #8a8985 55%, #3d3c39 100%); }
.ds-device__ear::after { background-image: linear-gradient(-30deg, transparent 45%, #222 45%, #222 55%, transparent 55%), radial-gradient(circle at 35% 35%, #e9e8e2, #8a8985 55%, #3d3c39 100%); }
.ds-device__head { grid-column: 2; display: grid; grid-template-columns: minmax(200px, 380px) 1fr auto; gap: 14px; align-items: center; padding: 12px 14px 8px; }
.ds-device__head .ds-title-strip { min-width: 0; }
.ds-device__body { grid-column: 2; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 16px; padding: 6px 14px 14px; align-items: stretch; }
body:not(.ds-is-lit) .ds-device__body, body:not(.ds-is-lit) .ds-device__head { opacity: .9; }
